package nl.smartstreamlabs.sbwdroneconfig;
import com.google.gson.*;import java.util.*;import java.io.*;import net.minecraft.core.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;import org.joml.*;
/** Original mesh hierarchy in block units. The authored 25 degree rest angle is applied once. */
public final class AdcGeometry{
 public static final AdcGeometry MODEL=new AdcGeometry();public record Bone(String name,int parent,Vector3d pivot,Vector3d rotation){}public record Part(int bone,AABB box){}
 public final List<Bone>bones=new ArrayList<>();public final List<Part>parts=new ArrayList<>();public final Map<String,Integer>names=new HashMap<>();public final int[][]cells,support;public final AABB bounds=new AABB(-3.5,0,-3.5,3.5,5,3.5);private final Map<Integer,VoxelShape[]>cache=new java.util.concurrent.ConcurrentHashMap<>();
 private AdcGeometry(){try(var r=new InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/assets/sbwdroneconfig/adc01/adc01.json")))){var j=JsonParser.parseReader(r).getAsJsonObject();for(var v:j.getAsJsonArray("bones")){var n=v.getAsJsonObject();names.put(n.get("name").getAsString(),bones.size());bones.add(new Bone(n.get("name").getAsString(),n.get("parent").getAsInt(),vec(n.getAsJsonArray("pivot")),vec(n.getAsJsonArray("rotation"))));}for(var v:j.getAsJsonArray("collision")){var n=v.getAsJsonObject();var a=n.getAsJsonArray("box");parts.add(new Part(n.get("bone").getAsInt(),new AABB(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble(),a.get(3).getAsDouble(),a.get(4).getAsDouble(),a.get(5).getAsDouble())));}cells=ints(j.getAsJsonArray("cells"));support=ints(j.getAsJsonArray("support"));}catch(IOException e){throw new ExceptionInInitializerError(e);}}
 private static Vector3d vec(JsonArray a){return new Vector3d(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble());}private static int[][]ints(JsonArray a){int[][]r=new int[a.size()][3];for(int i=0;i<r.length;i++)for(int k=0;k<3;k++)r[i][k]=a.get(i).getAsJsonArray().get(k).getAsInt();return r;}
 public Matrix4d[]poses(double yaw,double elevation,double recoil){return poses(yaw,elevation,recoil,0,5);}public Matrix4d[]poses(double yaw,double elevation,double recoil,double sensorYaw,double sensorPitch){var out=new Matrix4d[bones.size()];for(int i=0;i<out.length;i++){var b=bones.get(i);var r=new Vector3d(b.rotation);if(b.name.equals("Turret_Yaw"))r.y=yaw;if(b.name.equals("Gun_Elevation"))r.x=elevation;if(b.name.equals("Sensor_Pitch"))r.x=sensorPitch;if(b.name.equals("Sensor_Yaw"))r.y=sensorYaw;out[i]=new Matrix4d(b.parent<0?new Matrix4d():out[b.parent]).translate(b.pivot);if(b.name.equals("Barrel_Recoil"))out[i].translate(0,0,recoil);out[i].rotateZYX(java.lang.Math.toRadians(r.z),java.lang.Math.toRadians(r.y),java.lang.Math.toRadians(r.x)).translate(-b.pivot.x,-b.pivot.y,-b.pivot.z);}return out;}
 public static Matrix4d world(BlockPos p,Direction f){return new Matrix4d().translation(p.getX()+.5,p.getY(),p.getZ()+.5).rotateY(java.lang.Math.toRadians(180-f.toYRot()));}
 public static Vec3 point(Matrix4d m,Vector3d a){var v=m.transformPosition(new Vector3d(a));return new Vec3(v.x,v.y,v.z);}public static Vec3 direction(Matrix4d m){var v=m.transformDirection(new Vector3d(0,0,-1)).normalize();return new Vec3(v.x,v.y,v.z);}
 public Vec3 anchor(BlockPos p,Direction f,String name,double yaw,double elevation,double recoil){int i=names.get(name);return point(world(p,f).mul(poses(yaw,elevation,recoil)[i]),bones.get(i).pivot);}
 public Vec3 radar(BlockPos p,Direction f,double yaw,double pitch,double sy,double sp){int i=names.get("Radar_Anchor");return point(world(p,f).mul(poses(yaw,pitch,0,sy,sp)[i]),bones.get(i).pivot);}
 public Vec3 forward(Direction f,double yaw,double elevation){return direction(world(BlockPos.ZERO,f).mul(poses(yaw,elevation,0)[names.get("Muzzle_Anchor")]));}
 public BlockPos cell(BlockPos p,Direction f,int[]c){var v=point(world(BlockPos.ZERO,f),new Vector3d(c[0],c[1],c[2]));return p.offset((int)java.lang.Math.round(v.x-.5),c[1],(int)java.lang.Math.round(v.z-.5));}public BlockPos root(BlockPos p,Direction f,int part){return p.subtract(cell(BlockPos.ZERO,f,cells[java.lang.Math.min(cells.length-1,part)]));}
 public static AABB transform(Matrix4d m,AABB b){double x0=1e9,y0=1e9,z0=1e9,x1=-1e9,y1=-1e9,z1=-1e9;for(double x:new double[]{b.minX,b.maxX})for(double y:new double[]{b.minY,b.maxY})for(double z:new double[]{b.minZ,b.maxZ}){var v=m.transformPosition(new Vector3d(x,y,z));x0=java.lang.Math.min(x0,v.x);y0=java.lang.Math.min(y0,v.y);z0=java.lang.Math.min(z0,v.z);x1=java.lang.Math.max(x1,v.x);y1=java.lang.Math.max(y1,v.y);z1=java.lang.Math.max(z1,v.z);}return new AABB(x0,y0,z0,x1,y1,z1);}
 public List<AABB>boxes(BlockPos p,Direction f,float yaw,float pitch){var t=poses(yaw,pitch,0);var w=world(p,f);return parts.stream().map(b->transform(new Matrix4d(w).mul(t[b.bone]),b.box)).toList();}
 public VoxelShape shape(Direction f,int part,float yaw,float pitch){int y=java.lang.Math.floorMod(java.lang.Math.round(yaw/22.5f),16),e=java.lang.Math.max(0,java.lang.Math.min(5,java.lang.Math.round(pitch/15f))),key=f.get2DDataValue()*96+y*6+e;var values=cache.get(key);if(values==null){values=new VoxelShape[cells.length];var boxes=boxes(BlockPos.ZERO,f,y*22.5f,e*15);for(int i=0;i<cells.length;i++){var at=cell(BlockPos.ZERO,f,cells[i]);var s=Shapes.empty();for(var b:boxes){double a=java.lang.Math.max(0,b.minX-at.getX()),c=java.lang.Math.max(0,b.minY-at.getY()),d=java.lang.Math.max(0,b.minZ-at.getZ()),x=java.lang.Math.min(1,b.maxX-at.getX()),z=java.lang.Math.min(1,b.maxZ-at.getZ()),h=java.lang.Math.min(1,b.maxY-at.getY());if(x>a&&h>c&&z>d)s=Shapes.or(s,Shapes.box(a,c,d,x,h,z));}values[i]=s.optimize();}cache.put(key,values);}return values[java.lang.Math.min(part,values.length-1)];}
}
